<script setup lang="ts">
import { reconcileManuallyMergedDelivery } from "../utils/delivery-reconcile";
const props=defineProps<{title:string;brief:string}>();
interface Delivery {id:string;version:number;phase:string;cycle:number;sessionId?:string;childSessionId?:string;publication?:{number:number;url:string;headSha:string;targetHeadSha:string;targetBranch:string;ownerSessionId:string;branch:string};review?:{verdict:string;summary:string;headSha:string;baseSha:string;targetBranch:string;findings:Array<{severity:string}>;limitations:string[]};mergeReview?:{verdict:string;headSha:string;baseSha:string;targetBranch:string;findings:Array<{severity:string}>;limitations:string[]};reviewerSessionId?:string;mergeDecision?:{status:string;reason:string;commitSha?:string};error?:string;history:unknown[]}
const route=useRoute();const router=useRouter();const run=ref<Delivery>();const error=ref('');const working=ref(false);const revision=ref('');const reconcileInfo=ref('');const reconcileHead=ref('');let operationId:string|undefined;let timer:ReturnType<typeof setTimeout>|undefined;let disposed=false;
const stopped=new Set(['human_review','ready','blocked','needs_revision','cancelled','merged']);
const reconcilable=new Set(['human_review','ready','blocked']);
interface ReconcileEvidence {merged:boolean;headSha:string;targetBranch:string;commitSha:string}
const evidence=ref<ReconcileEvidence>({merged:false,headSha:'',targetBranch:'',commitSha:''});
const evidenceHeadValid=computed(()=>/^[a-f0-9]{40}$/.test(evidence.value.headSha.trim()));
const evidenceCommitValid=computed(()=>!evidence.value.commitSha.trim()||/^[a-f0-9]{40}$/.test(evidence.value.commitSha.trim()));
const canReconcile=computed(()=>!!run.value?.publication&&reconcilable.has(run.value.phase)&&evidence.value.merged&&evidenceHeadValid.value&&evidence.value.targetBranch.trim().length>0&&evidenceCommitValid.value);
async function checkManualMerge(){const saved=run.value;if(!saved||working.value||!saved.publication||!reconcilable.has(saved.phase))return;const publication=saved.publication;const outcome=reconcileManuallyMergedDelivery(saved,evidence.value.merged?{number:publication.number,merged:true,state:'closed',headSha:evidence.value.headSha.trim(),targetBranch:evidence.value.targetBranch.trim(),commitSha:evidence.value.commitSha.trim()||undefined}:undefined);reconcileInfo.value=outcome.reason+(outcome.eligible&&saved.phase!=='merged'?' The saved delivery is unchanged by this check; marking it merged needs a separately reviewed factory change.':'');reconcileHead.value=outcome.eligible?(outcome.commitSha||''):'';}
const cockpit=useCockpit();
async function remember(value:Delivery){try{const row=cockpit.items.value.runs.find(r=>r.id===value.id);await cockpit.save('runs',value.id,{label:props.title||'Delivery loop',station:'loop'},row?.version??0);}catch{/* Keep the authoritative delivery link even if its history index is unavailable. */}}
function schedule(){if(!disposed&&run.value&&!stopped.has(run.value.phase))timer=setTimeout(()=>void refresh(),3000);}
async function start(){if(working.value)return;working.value=true;error.value='';operationId??=crypto.randomUUID();try{run.value=await $fetch<Delivery>('/factory/delivery',{method:'POST',body:{operationId,title:props.title,brief:props.brief},retry:0});await router.replace({query:{...route.query,delivery:run.value.id}});await remember(run.value);operationId=undefined;schedule();}catch{error.value='Could not confirm the loop start. Retry uses the same operation ID.';}finally{working.value=false;}}
async function refresh(){if(!run.value||working.value)return;working.value=true;try{run.value=await $fetch<Delivery>(`/factory/delivery/${encodeURIComponent(run.value.id)}`,{retry:0});error.value='';}catch{error.value='Could not refresh this delivery. Reconnect to the same run.';}finally{working.value=false;schedule();}}
async function resume(){if(!run.value||working.value)return;working.value=true;try{run.value=await $fetch<Delivery>(`/factory/delivery/${encodeURIComponent(run.value.id)}/resume`,{method:'POST',body:{operationId:operationId??=crypto.randomUUID()},retry:0});operationId=undefined;error.value='';schedule();}catch{error.value='Could not resume this delivery. The existing operation is retained.';}finally{working.value=false;}}
async function cancel(){if(!run.value)return;clearTimeout(timer);try{run.value=await $fetch<Delivery>(`/factory/delivery/${encodeURIComponent(run.value.id)}/cancel`,{method:'POST',retry:0});}catch{error.value='Cancellation is unconfirmed. Reconnect to check the same run.';}}
async function revise(){if(!run.value||working.value)return;working.value=true;operationId??=crypto.randomUUID();try{run.value=await $fetch<Delivery>(`/factory/delivery/${encodeURIComponent(run.value.id)}/revise`,{method:'POST',body:{operationId,brief:revision.value},retry:0});operationId=undefined;revision.value='';error.value='';schedule();}catch{error.value='Could not confirm the revision. Your request is retained.';}finally{working.value=false;}}
watch(()=>route.query.delivery,async id=>{clearTimeout(timer);if(typeof id!=='string')return;try{run.value=await $fetch<Delivery>(`/factory/delivery/${encodeURIComponent(id)}`);schedule();}catch{error.value='Could not load this delivery. Keep its URL to retry.';}},{immediate:true});
onBeforeUnmount(()=>{disposed=true;clearTimeout(timer);});
</script>
<template><section class="panel" style="padding:24px;margin-top:24px"><div class="panel-heading"><h2>Build and review loop</h2><UBadge v-if="run">{{run.phase}}</UBadge></div><p class="muted">The worker creates a PR, an independent agent reviews it, and findings return to the branch owner. The workflow continues when you close this page. Low-risk changes can merge automatically after independent checks.</p><UButton :disabled="!title.trim()||brief.trim().length<20||working" :loading="working" @click="start">Start delivery from this draft</UButton><p v-if="error" role="alert">{{error}}</p><template v-if="run"><p>Delivery {{run.id}} · revision {{run.cycle}}</p><p v-if="run.mergeDecision">{{run.mergeDecision.reason}}</p><p v-if="run.error">{{run.error}}</p><p v-if="run.review">{{run.review.summary}}</p><UButton v-if="run.publication" :to="run.publication.url" target="_blank">Open PR #{{run.publication.number}}</UButton><template v-if="run.publication&&reconcilable.has(run.phase)"><UFormField label="GitHub head SHA for PR #{{run.publication.number}}" name="reconcile-head" help="Copy the exact head SHA from the merged GitHub PR."><UInput v-model="evidence.headSha" class="w-full" placeholder="40-character commit SHA" /></UFormField><UFormField label="GitHub target branch" name="reconcile-target"><UInput v-model="evidence.targetBranch" class="w-full" placeholder="main" /></UFormField><UFormField label="Merge commit SHA (optional)" name="reconcile-commit" help="Recorded for reference only; the candidate head above must match the reviewed head."><UInput v-model="evidence.commitSha" class="w-full" placeholder="40-character merge commit SHA" /></UFormField><p class="muted small">Compare the GitHub PR page against the recorded candidate head and target above before confirming.</p><URadioGroup :model-value="evidence.merged?'merged':'unknown'" :items="[{value:'unknown',label:'Not confirmed'},{value:'merged',label:'Merged on GitHub'}]" orientation="horizontal" name="reconcile-merged" aria-label="GitHub merge state for the recorded PR" @update:model-value="evidence.merged=$event==='merged'" /><UButton variant="outline" :disabled="working||!canReconcile" @click="checkManualMerge">Check manual merge</UButton><UAlert v-if="reconcileInfo" color="info" variant="soft" title="Manual-merge check" :description="reconcileInfo" /><p v-if="reconcileHead" class="muted small">Merge commit {{reconcileHead}}</p></template><UButton v-if="run.phase==='blocked'||(run.phase==='human_review'&&!run.publication)" variant="outline" :disabled="working" @click="resume">Resume blocked observation</UButton><UButton v-else variant="outline" :disabled="working" @click="refresh">Refresh status</UButton><UButton v-if="!stopped.has(run.phase)" variant="ghost" @click="cancel">Stop delivery</UButton><template v-if="['ready','human_review','blocked','needs_revision'].includes(run.phase)"><UTextarea v-model="revision" placeholder="Describe the next revision for the branch owner"/><UButton :disabled="revision.trim().length<20||working" @click="revise">Request revision</UButton></template></template></section></template>
